INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B304447', 'ΑΙΜΑ, ΛΑΝΘΑΝΩΝ, (Π.Χ. ΕΛΕΓΧΟΣ ΛΑΝΘΑΝΟΥΣΑΣ ΑΙΜΟΡΡΑΓΙΑΣ), ΜΕ ΔΡΑΣΤΗΡΙΟΤΗΤΑ ΥΠΕΡΟΞΕΙΔΙΑΣΗΣ, ΠΟΙΟΤΙΚΗ. ΚΟΠΡΑΝΑ,  ΔΙΑΔΟΧΙΚΗ ΣΥΛΛΟΓΗ ΔΕΙΓΜΑΤΩΝ ΜΕ ΕΝΙΑΙΟ ΠΡΟΣΔΙΟΡΙΣΜΟ, ΓΙΑ ΔΟΚΙΜΑΣΙΑ ΔΙΑΛΟΓΗΣ (SCREENING) ΕΝΤΕΡΙΚΟΥ ΝΕΟΠΛΑΣΜΑΤΟΣ (ΠΧ. ΣΤΟΝ ΑΣΘΕΝΗ  ΧΟΡΗΓΗΘΗΚΑΝ ΤΡΙΑ ΔΟΧΕΙΑ ΓΙΑ ΔΙΑΔΟΧΙΚΗ ΣΥΛΛΟΓΗ)', 'Surgery', 120, 1396, 'Operating');
INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B304449', 'ΑΙΜΑ, ΛΑΝΘΑΝΩΝ, (Π.Χ. ΕΛΕΓΧΟΣ ΛΑΝΘΑΝΟΥΣΑΣ ΑΙΜΟΡΡΑΓΙΑΣ), ΜΕ ΔΡΑΣΤΗΡΙΟΤΗΤΑ ΥΠΕΡΟΞΕΙΔΙΑΣΗΣ, ΠΟΙΟΤΙΚΗ. ΑΛΛΕΣ ΠΗΓΕΣ ΔΕΙΓΜΑΤΩΝ', 'Surgery', 55, 608, 'Procedure');
INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B304451', 'ΑΙΜΑ, ΛΑΝΘΑΝΩΝ, (Π.Χ. ΕΛΕΓΧΟΣ ΛΑΝΘΑΝΟΥΣΑΣ ΑΙΜΟΡΡΑΓΙΑΣ), ΜΕ ΔΡΑΣΤΗΡΙΟΤΗΤΑ ΥΠΕΡΟΞΕΙΔΙΑΣΗΣ, ΠΟΙΟΤΙΚΗ. ΚΟΠΡΑΝΑ,  1-3 ΤΑΥΤΟΧΡΟΝΟΙ ΠΡΟΣΔΙΟΡΙΣΜΟΙ, ΠΟΥ ΕΚΤΕΛΟΥΝΤΑΙ ΓΙΑ ΕΛΕΓΧΟ ΑΛΛΗΣ ΚΑΤΑΣΤΑΣΗΣ ΠΛΗΝ ΔΟΚΙΜΑΣΙΑΣ ΔΙΑΛΟΓΗΣ (SCREENING) ΕΝΤΕΡΙΚΟΥ ΝΕΟΠΛΑΣΜΑΤΟΣ', 'Therapeutic', 82, 635, 'Procedure');
