INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.82', 'ΠΟΣΟΤΙΚΗ ΕΚΤΙΜΗΣΗ RNA ΜΕΤΑΓΡΑΦΩΝ ΜΕ REAL TIME PCR ΜΕ ΦΘΟΡΙΖΟΝΤΕΣ ΑΝΙΧΝΕΥΤΕΣ ΑΝΑ ΣΤΟΧΟ ΜΕ ΕΣΩΤΕΡΙΚΟΥΣ ΚΑΙ ΕΞΩΤΕΡΙΚΟΥΣ ΜΑΡΤΥΡΕΣ (ΕΠΙΠΛΕΟΝ ΤΩΝ ΚΩΔΙΚΩΝ ΤΩΝ ΜΕΜΟΝΩΜΕΝΩΝ ΑΝΤΙΔΡΑΣΕΩΝ) ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Therapeutic', 85, 763, 'Procedure');
