INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.84', 'ΠΟΣΟΤΙΚΗ ΕΚΤΙΜΗΣΗ microRNAs ΜΕ REAL TIME PCR, ΑΝΑ ΣΤΟΧΟ ΜΕ ΕΣΩΤΕΡΙΚΟΥΣ ΜΑΡΤΥΡΕΣ (ΕΠΙΠΛΕΟΝ ΤΩΝ ΚΩΔΙΚΩΝ ΤΩΝ ΜΕΜΟΝΩΜΕΝΩΝ ΑΝΤΙΔΡΑΣΕΩΝ) ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Diagnostic', 53, 1476, 'Operating');
INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.85', 'ΠΡΟΣΔΙΟΡΙΣΜΟΣ ΝΟΥΚΛΕΟΤΙΔΙΚΗΣ ΑΛΛΗΛΟΥΧΙΑΣ ΜΕΤΑ ΑΠΟ ΚΛΩΝΟΠΟΙΗΣΗ ΣΕ ΦΟΡΕΑ, ΝΟΗΜΑΤΙΚΟΣ (SENSE) ΚΑΙ ΑΝΤΙΝΟΗΜΑΤΙΚΟΣ (ANTISENSE), ΑΝΑ ΤΜΗΜΑ DNA ΜΕΧΡΙ 500 ΒΑΣΕΙΣ ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Surgery', 98, 1080, 'Procedure');
INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.86', 'ΑΥΤΟΜΑΤΟΠΟΙΗΜΕΝΟΣ ΠΡΟΣΔΙΟΡΙΣΜΟΣ ΝΟΥΚΛΕΟΤΙΔΙΚΗΣ ΑΛΛΗΛΟΥΧΙΑΣ ΣΕ ΠΡΑΓΜΑΤΙΚΟ ΧΡΟΝΟ (PYROSEQUENCING), ΠΟΛΛΑΠΛΕΣ ΔΟΚΙΜΑΣΙΕΣ, ΣΥΜΠΕΡΙΛΑΜΒΑΝΟΜΕΝΩΝ ΤΩΝ ΣΧΕΤΙΚΩΝ ΚΩΔΙΚΩΝ ΠΑΡΑΣΚΕΥΗΣ ΤΩΝ ΔΕΙΓΜΑΤΩΝ ΚΑΙ ΤΗΣ PCR ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Therapeutic', 76, 1347, 'Operating');
