INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.89', 'ΠΡΟΣΔΙΟΡΙΣΜΟΣ ΑΔΡΩΝ ΕΠΑΥΞΗΣΕΩΝ / ΕΛΛΕΙΨΕΩΝ ΣΕ DNA ΜΕ CGH ΣΕ ΜΙΚΡΟΣΥΣΤΟΙΧΙΕΣ (array-CGH), ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Therapeutic', 57, 875, 'Procedure');
