INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.92', 'ΜΟΡΙΑΚΟΣ ΓΕΝΕΤΙΚΟΣ ΕΛΕΓΧΟΣ ΣΥΝΔΡΟΜΩΝ ΠΟΥ ΣΧΕΤΙΖΟΝΤΑΙ ΜΕ ΝΕΟΠΛΑΣΜΑΤΙΚΕΣ ΠΑΘΗΣΕΙΣ (π.χ. FAP, HNPCC, MEN1A, MEN1B, MEN2, JP, COWDEN, κ.ά.) ΕΠΙΠΛΕΟΝ ΤΩΝ ΚΩΔΙΚΟΥ ΕΦΑΡΜΟΖΟΜΕΝΗΣ ΤΕΧΝΙΚΗΣ ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Diagnostic', 76, 770, 'Operating');
INSERT IGNORE INTO Medical_Procedures_Catalog (procedure_code, name, category, duration, cost, required_room_type) VALUES ('B316705.93', 'ΜΟΡΙΑΚΟΣ ΓΕΝΕΤΙΚΟΣ ΕΛΕΓΧΟΣ ΟΙΚΟΓΕΝΟΥΣ ΚΑΡΚΙΝΟΥ ΜΑΣΤΟΥ - ΩΟΘΗΚΩΝ (ΕΛΕΓΧΟΣ ΓΟΝΙΔΙΩΝ BRCA1- BRCA2) ΕΠΙΠΛΕΟΝ ΤΟΥ ΚΩΔΙΚΟΥ ΕΦΑΡΜΟΖΟΜΕΝΗΣ ΤΕΧΝΙΚΗΣ ΜΕ ΕΡΜΗΝΕΙΑ ΚΑΙ ΕΚΘΕΣΗ ΑΠΟ ΕΙΔΙΚΟ ΙΑΤΡΟ', 'Surgery', 70, 412, 'Procedure');
