-- ==========================================
SELECT 
    CONCAT('D', d.department_id, '-B', n.num), -- Δημιουργεί ονόματα τύπου D1-B1, D1-B2 κλπ.
    IF(d.department_id = 4, 'ICU Bed', 'Standard Bed'), -- Αν είναι η ΜΕΘ (ID 4) βάζει ICU Bed
    'Available', 
    d.department_id
FROM `Department` d
CROSS JOIN (
    -- Αυτό το κομμάτι παράγει τους αριθμούς από 1 έως 40 (40 κρεβάτια * 15 τμήματα = 600 κλίνες!)
    SELECT a.N + b.N * 10 + 1 AS num
    FROM 
        (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a,
        (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3) b
) n
ORDER BY d.department_id, n.num;

-- ==========================================
-- Δημιουργία Ομάδων (Teams) ανά Τμήμα
-- ==========================================

-- Δημιουργία 30 Ομάδων (2 ομάδες για κάθε ένα από τα 15 τμήματα)
SELECT 
    a.num AS team_id, 
    CEIL(a.num / 2.0) AS department_id
FROM (
    SELECT n1.N + n2.N * 10 + 1 AS num 
    FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) n1,
         (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3) n2
) a
WHERE a.num <= 30;

-- ======================================================================
-- ΒΗΜΑ Α: ΤΟΠΟΘΕΤΗΣΗ ΠΡΑΓΜΑΤΙΚΟΥ ΠΡΟΣΩΠΙΚΟΥ ΣΤΙΣ 30 ΟΜΑΔΕΣ
-- ======================================================================

-- 1. Τοποθέτηση των ΠΡΑΓΜΑΤΙΚΩΝ Νοσηλευτών στις ομάδες
SELECT (`department_id` * 2) - FLOOR(RAND() * 2), `AMKA`
FROM `Nurse` WHERE `AMKA` NOT LIKE '555%';

-- 2. Τοποθέτηση των ΠΡΑΓΜΑΤΙΚΩΝ Διοικητικών στις ομάδες
SELECT (`department_id` * 2) - FLOOR(RAND() * 2), `AMKA`
FROM `Admin` WHERE `AMKA` NOT LIKE '333%';

-- 3. Τοποθέτηση των ΠΡΑΓΜΑΤΙΚΩΝ Γιατρών στις ομάδες 
SELECT (`department_id` * 2) - FLOOR(RAND() * 2), `doctor_AMKA`
FROM `Doctor_Department` WHERE `doctor_AMKA` NOT LIKE '444%';

-- ======================================================================
-- 1. ΕΝΙΣΧΥΣΗ ΠΡΟΣΩΠΙΚΟΥ ΓΙΑ ΤΗΝ ΚΑΛΥΨΗ ΤΩΝ TRIGGERS (Κλίμακα 15 Τμημάτων)
-- ======================================================================

-- -------- ΕΦΕΔΡΙΚΟΙ ΔΙΟΙΚΗΤΙΚΟΙ (60 Άτομα | 2 ΑΝΑ ΟΜΑΔΑ) --------
SELECT 
    CONCAT('333000000', LPAD(num, 2, '0')), 
    ELT((num % 10) + 1, 'Αλέξανδρος', 'Μαρία', 'Γεώργιος', 'Αικατερίνη', 'Δημήτριος', 'Ελένη', 'Ιωάννης', 'Σοφία', 'Κωνσταντίνος', 'Άννα'),
    ELT(((num * 7) % 10) + 1, 'Παπαδόπουλος', 'Γεωργίου', 'Νικολάου', 'Μακρής', 'Λαζάρου', 'Αντωνίου', 'Δημητρίου', 'Στεργίου', 'Βασιλείου', 'Ρήγας'),
    FLOOR(25 + (RAND() * 30)), 
    CONCAT('admin_extra_', num, '@hospital.gr'), 
    CURDATE(), 
    'Admin'
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5) b) n WHERE num <= 60;

SELECT CONCAT('333000000', LPAD(num, 2, '0')), 'Βοηθός Βάρδιας', 'Back Office', FLOOR((num - 1) / 4) + 1
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5) b) n WHERE num <= 60;

SELECT FLOOR((num - 1) / 2) + 1, CONCAT('333000000', LPAD(num, 2, '0'))
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5) b) n WHERE num <= 60;




-- -------- ΕΦΕΔΡΙΚΟΙ ΓΙΑΤΡΟΙ (90 Άτομα | 3 ΑΝΑ ΟΜΑΔΑ) --------

-- 1. Μπαίνουν στο Staff (Με τα ελληνικά ονόματα ΚΑΙ έγκυρα τηλέφωνα)
SELECT 
    CONCAT('444000000', LPAD(num, 2, '0')), 
    ELT((num % 10) + 1, 'Αλέξανδρος', 'Μαρία', 'Γεώργιος', 'Αικατερίνη', 'Δημήτριος', 'Ελένη', 'Ιωάννης', 'Σοφία', 'Κωνσταντίνος', 'Άννα'),
    ELT(((num * 3) % 10) + 1, 'Παπαδόπουλος', 'Γεωργίου', 'Νικολάου', 'Μακρής', 'Λαζάρου', 'Αντωνίου', 'Δημητρίου', 'Στεργίου', 'Βασιλείου', 'Ρήγας'),
    40, 
    CONCAT('doc_', num, '@hospital.gr'), 
    CONCAT('69440000', LPAD(num, 2, '0')), 
    DATE_SUB(CURDATE(), INTERVAL FLOOR(RAND() * 1095) DAY),
    'Doctor'
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8) b) n WHERE num <= 90;

-- 2. Μπαίνουν στο Doctor (Με 100% σίγουρα δεδομένα που δέχεται η βάση σου)
SELECT 
    CONCAT('444000000', LPAD(num, 2, '0')), 
    CONCAT('MED-EXT-', num), 
    'Παθολόγος', 
    'Consultant_A'
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8) b) n WHERE num <= 90;

-- 3. Μπαίνουν στα Τμήματα (6 ανά τμήμα)
SELECT CONCAT('444000000', LPAD(num, 2, '0')), FLOOR((num - 1) / 6) + 1
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8) b) n WHERE num <= 90;

-- 4. Μπαίνουν στις Ομάδες (ΑΚΡΙΒΩΣ 3 ΑΝΑ ΟΜΑΔΑ)
SELECT FLOOR((num - 1) / 3) + 1, CONCAT('444000000', LPAD(num, 2, '0'))
FROM (SELECT a.N + b.N * 10 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8) b) n WHERE num <= 90;

-- ======================================================================
-- ΕΦΕΔΡΙΚΟΙ ΝΟΣΗΛΕΥΤΕΣ (180 Άτομα | 6 ΑΝΑ ΟΜΑΔΑ)
-- ======================================================================

SET SQL_SAFE_UPDATES = 0;
-- Καθαρίζουμε τυχόν παλιά/μισά δεδομένα νοσηλευτών για να είμαστε 100% σίγουροι
DELETE FROM `Team_Staff` WHERE `staff_AMKA` LIKE '555%';
DELETE FROM `Nurse` WHERE `AMKA` LIKE '555%';
DELETE FROM `Staff` WHERE `AMKA` LIKE '555%';
SET SQL_SAFE_UPDATES = 1;

-- 1. Προσθήκη στο Staff
SELECT 
    CONCAT('55500000', LPAD(num, 3, '0')), 
    ELT((num % 10) + 1, 'Αλέξανδρος', 'Μαρία', 'Γεώργιος', 'Αικατερίνη', 'Δημήτριος', 'Ελένη', 'Ιωάννης', 'Σοφία', 'Κωνσταντίνος', 'Άννα'),
    ELT(((num * 9) % 10) + 1, 'Παπαδόπουλος', 'Γεωργίου', 'Νικολάου', 'Μακρής', 'Λαζάρου', 'Αντωνίου', 'Δημητρίου', 'Στεργίου', 'Βασιλείου', 'Ρήγας'),
    FLOOR(22 + (RAND() * 35)), 
    CONCAT('nurse_extra_', num, '@hospital.gr'), 
    CURDATE(), 
    'Nurse'
FROM (SELECT a.N + b.N * 10 + c.N * 100 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b, (SELECT 0 AS N UNION SELECT 1) c) n WHERE num <= 180;

-- 2. Προσθήκη στον πίνακα Nurse (μοιρασμένοι στα 15 τμήματα)
SELECT 
    CONCAT('55500000', LPAD(num, 3, '0')), 
    ELT(FLOOR(1 + (RAND() * 3)), 'Assistant', 'Nurse', 'Head'), 
    FLOOR((num - 1) / 12) + 1
FROM (SELECT a.N + b.N * 10 + c.N * 100 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b, (SELECT 0 AS N UNION SELECT 1) c) n WHERE num <= 180;

-- 3. Προσθήκη στις 30 Ομάδες (6 ακριβώς ανά ομάδα!)
SELECT FLOOR((num - 1) / 6) + 1, CONCAT('55500000', LPAD(num, 3, '0'))
FROM (SELECT a.N + b.N * 10 + c.N * 100 + 1 AS num FROM (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) a, (SELECT 0 AS N UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9) b, (SELECT 0 AS N UNION SELECT 1) c) n WHERE num <= 180;


-- ======================================================================
-- ΒΗΜΑ Γ: ΜΑΖΙΚΟΣ ΚΑΘΑΡΙΣΜΟΣ ΔΙΠΛΟΤΥΠΙΩΝ (Αφού έχουν μπει όλοι!)
-- ======================================================================
SET SQL_SAFE_UPDATES = 0;

DELETE t1 FROM `Team_Staff` t1
JOIN `Team_Staff` t2 
ON t1.`staff_AMKA` = t2.`staff_AMKA` AND t1.`team_id` > t2.`team_id`;

-- ======================================================================
-- ΒΗΜΑ Δ: ΔΗΜΙΟΥΡΓΙΑ ΒΑΡΔΙΩΝ (Shifts) - Τώρα ο πίνακας είναι πεντακάθαρος
-- ======================================================================
DELETE FROM `Shift`;
SET SQL_SAFE_UPDATES = 1;

SELECT 
    DATE_ADD('2026-01-01', INTERVAL n.day_num DAY),
    IF(t.team_id % 2 = 1, 'Morning', 'Evening'),
    t.team_id,
    t.department_id
FROM `Team` t
CROSS JOIN (
    SELECT 0 AS day_num UNION SELECT 1 UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
) n;


-- ==========================================
-- 2. Δήλωση Αλλεργιών Ασθενών
-- ==========================================
SELECT 
    p.`AMKA`, 
    (SELECT `substance_name` FROM `Active_Substance` ORDER BY RAND() LIMIT 1)
FROM `Patient` p
ORDER BY RAND()
LIMIT 50;

-- ==========================================
-- Δημιουργία Διαλογών (Triage) για όλους τους ασθενείς
-- ==========================================
SELECT 
    DATE_ADD('2026-01-01 08:00:00', INTERVAL FLOOR(RAND() * 120) HOUR), 
    ELT(FLOOR(1 + (RAND() * 5)), 'Υψηλός πυρετός και δύσπνοια', 'Έντονος πόνος στο στήθος', 'Κοιλιακό άλγος και ναυτία', 'Τραυματισμός από πτώση', 'Έντονη κεφαλαλγία και ίλιγγος'),
    FLOOR(1 + (RAND() * 5)), 
    IF(RAND() > 0.1, 'Admission', 'Discharged'), 
    p.`AMKA`,
    (SELECT `AMKA` FROM `Nurse` ORDER BY RAND() LIMIT 1)
FROM `Patient` p;

-- ==========================================
-- ΕΙΣΑΓΩΓΗ ΝΟΣΗΛΕΙΩΝ (Admissions)
-- ==========================================
CREATE TEMPORARY TABLE `Temp_Admission_Data` AS
SELECT 
    DATE_ADD(t.arrival_date, INTERVAL 2 HOUR) AS date_in,
    t.patient_AMKA,
    b.bed_number,
    b.department_id,
    (SELECT `KEN_code` FROM `KEN` ORDER BY RAND() LIMIT 1) AS KEN_code,
    (SELECT `ICD-10_code` FROM `ICD-10_catalog` ORDER BY RAND() LIMIT 1) AS diagnosis_in_code
FROM (
    SELECT `patient_AMKA`, `arrival_date`, ROW_NUMBER() OVER (ORDER BY `arrival_date`) as rn
    FROM `Triage`
    WHERE `outcome` = 'Admission'
) t
JOIN (
    SELECT `bed_number`, `department_id`, ROW_NUMBER() OVER(ORDER BY RAND()) as rn
    FROM `Bed`
    WHERE `status` = 'Available'
) b ON t.rn = b.rn;

SELECT `date_in`, NULL, `patient_AMKA`, `bed_number`, `department_id`, `KEN_code`, `diagnosis_in_code`
FROM `Temp_Admission_Data`;

DROP TEMPORARY TABLE `Temp_Admission_Data`;

SET SQL_SAFE_UPDATES = 0;
UPDATE `Bed` 
SET `status` = 'Occupied'
WHERE `bed_number` IN (SELECT `bed_number` FROM `Admission` WHERE `date_out` IS NULL);
SET SQL_SAFE_UPDATES = 1;

-- ========================================================= --
                     -- Prescription --
-- ========================================================= --

SET SQL_SAFE_UPDATES = 0;
DROP TEMPORARY TABLE IF EXISTS `Temp_Numbered_Meds`;

-- 1. Φτιάχνουμε έναν προσωρινό πίνακα που βάζει νούμερα (1, 2, 3...) στα φάρμακα
CREATE TEMPORARY TABLE `Temp_Numbered_Meds` AS
SELECT `EMA_code`, ROW_NUMBER() OVER() as rn
FROM `Medication`;

-- 2. Βρίσκουμε πόσα ακριβώς φάρμακα έχουμε
SET @max_meds = (SELECT COUNT(*) FROM `Temp_Numbered_Meds`);

-- 3. Κάνουμε την Εισαγωγή αστραπιαία!
SELECT 
    a.`admission_code`,
    -- Επιλέγουμε έναν γιατρό γρήγορα
    (SELECT `doctor_AMKA` FROM `Doctor_Department` WHERE `department_id` = a.`department_id` LIMIT 1),
    a.`patient_AMKA`,
    -- Διαλέγουμε φάρμακο με O(1) ταχύτητα, χωρίς να "λιώνει" η βάση
    tm.`EMA_code`,
    a.`date_in`,                                    
    DATE_ADD(a.`date_in`, INTERVAL 7 DAY),          
    ELT(FLOOR(1 + (RAND() * 3)), '1 δισκίο', '10ml', '1 κάψουλα'),
    ELT(FLOOR(1 + (RAND() * 3)), 'Ανά 8 ώρες', '1 φορά την ημέρα', 'Πρωί και Βράδυ')
FROM `Admission` a
CROSS JOIN (
    SELECT 1 AS num UNION SELECT 2 
) n
-- Εδώ γίνεται η μαγεία: Κληρώνει έναν τυχαίο αριθμό από το 1 έως το Max και τον κάνει JOIN!
JOIN `Temp_Numbered_Meds` tm ON tm.rn = FLOOR(1 + (RAND() * @max_meds));

-- 4. Σκουπίζουμε τον προσωρινό πίνακα
DROP TEMPORARY TABLE `Temp_Numbered_Meds`;
SET SQL_SAFE_UPDATES = 1;

-- ==========================================
-- ΕΡΓΑΣΤΗΡΙΑΚΕΣ ΕΞΕΤΑΣΕΙΣ
-- ==========================================
CREATE TEMPORARY TABLE `Temp_Lab_Data` AS
SELECT 
    ELT(FLOOR(1 + (RAND() * 5)), 'Γενική Αίματος', 'Ακτινογραφία Θώρακος', 'Μαγνητική Τομογραφία (MRI)', 'Υπέρηχος Κοιλίας', 'Βιοχημικός Έλεγχος') AS `type`,
    DATE_ADD(a.`date_in`, INTERVAL FLOOR(1 + (RAND() * 48)) HOUR) AS `test_date`,
    ELT(FLOOR(1 + (RAND() * 3)), 'Φυσιολογικά ευρήματα', 'Οριακές τιμές - Χρήζει παρακολούθησης', 'Ενδείξεις φλεγμονής - Εκτός φυσιολογικών ορίων') AS `result`,
    ROUND(20 + (RAND() * 150), 2) AS `cost`,
    a.`admission_code`,
    (SELECT `doctor_AMKA` FROM `Doctor_Department` WHERE `department_id` = a.`department_id` ORDER BY RAND() LIMIT 1) AS `doctor_AMKA`
FROM `Admission` a
CROSS JOIN (
    SELECT 1 AS num UNION SELECT 2 UNION SELECT 3
) n;

SELECT `type`, `test_date`, `result`, `cost`, `admission_code`, `doctor_AMKA`
FROM `Temp_Lab_Data`;

DROP TEMPORARY TABLE `Temp_Lab_Data`;

-- ==========================================
-- ΚΛΙΝΙΚΕΣ ΠΡΑΞΕΙΣ 
-- ==========================================
SET SQL_SAFE_UPDATES = 0;

DROP TEMPORARY TABLE IF EXISTS `Temp_Clinical_Events`;
DROP TEMPORARY TABLE IF EXISTS `Temp_Event_Base`;

CREATE TEMPORARY TABLE `Temp_Event_Base` AS
SELECT 
    a.`admission_code`,
    a.`date_in`,
    a.`department_id`,
    (SELECT `procedure_code` FROM `Medical_Procedures_Catalog` ORDER BY RAND() LIMIT 1) AS `proc_code`
FROM `Admission` a;

CREATE TEMPORARY TABLE `Temp_Clinical_Events` AS
SELECT 
    DATE_ADD(tb.`date_in`, INTERVAL 10 + (tb.`admission_code` * 2) HOUR) AS `start_time`,
    tb.`proc_code` AS `procedure_code`,
    tb.`admission_code`,
    (SELECT `room_id` FROM `Room` WHERE `type` = mpc.`required_room_type` ORDER BY RAND() LIMIT 1) AS `room_id`,
    IF(mpc.`category` = 'Surgery' OR RAND() > 0.5, 
       (SELECT `doctor_AMKA` FROM `Doctor_Department` WHERE `department_id` = tb.`department_id` ORDER BY RAND() LIMIT 1),
       NULL
    ) AS `main_surgeon_AMKA`
FROM `Temp_Event_Base` tb
JOIN `Medical_Procedures_Catalog` mpc ON tb.`proc_code` = mpc.`procedure_code`;

SELECT `start_time`, `procedure_code`, `admission_code`, `room_id`, `main_surgeon_AMKA`
FROM `Temp_Clinical_Events`
WHERE `room_id` IS NOT NULL;

DROP TEMPORARY TABLE IF EXISTS `Temp_Clinical_Events`;
DROP TEMPORARY TABLE IF EXISTS `Temp_Event_Base`;
SET SQL_SAFE_UPDATES = 1;

-- ==========================================
-- ΒΟΗΘΟΙ ΚΛΙΝΙΚΩΝ ΠΡΑΞΕΩΝ (Θωρακισμένο)
-- ==========================================

-- 1. Προσθήκη Νοσηλευτών (Αυτοί δεν έχουν θέμα με τον χειρουργό)
SELECT 
    ce.`clinical_event_code`,
    (SELECT `AMKA` FROM `Nurse` ORDER BY RAND() LIMIT 1)
FROM `Clinical_Event` ce;

-- 2. Προσθήκη Γιατρών ως βοηθών (Με έλεγχο να μην είναι ο ίδιος ο χειρουργός)
SELECT 
    ce.`clinical_event_code`,
    CONCAT('444000000', LPAD((ce.`clinical_event_code` % 90) + 1, 2, '0'))
FROM `Clinical_Event` ce
JOIN `Medical_Procedures_Catalog` mpc ON ce.`procedure_code` = mpc.`procedure_code`
WHERE mpc.`category` = 'Surgery'
-- ΕΔΩ ΕΙΝΑΙ Η ΛΥΣΗ: Δεν βάζουμε βοηθό αν είναι ο ίδιος ο χειρουργός
AND CONCAT('444000000', LPAD((ce.`clinical_event_code` % 90) + 1, 2, '0')) != ce.`main_surgeon_AMKA`;

-- ==========================================
-- ΤΟ GRAND FINALE: Εξιτήρια & Αξιολογήσεις!
-- ==========================================
SET SQL_SAFE_UPDATES = 0;

UPDATE `Admission` 
SET 
    `date_out` = DATE_ADD(`date_in`, INTERVAL FLOOR(3 + RAND() * 10) DAY),
    `diagnosis_out_code` = ELT(FLOOR(1 + (RAND() * 3)), 'Z71.1', 'Z03.9', 'Z00.0')
WHERE `date_out` IS NULL 
LIMIT 130;

UPDATE `Bed` b
JOIN `Admission` a ON b.`bed_number` = a.`bed_number`
SET b.`status` = 'Available'
WHERE a.`date_out` IS NOT NULL;

SET SQL_SAFE_UPDATES = 1;

SELECT 
    FLOOR(1 + (RAND() * 5)), 
    FLOOR(1 + (RAND() * 5)),
    FLOOR(1 + (RAND() * 5)),
    FLOOR(1 + (RAND() * 5)),
    `admission_code`
FROM `Admission`
WHERE `date_out` IS NOT NULL
ORDER BY RAND()
LIMIT 100;

SELECT 
    FLOOR(1 + (RAND() * 5)), 
    p.`doctor_AMKA`,
    p.`admission_code`
FROM `Prescription` p
JOIN `Admission` a ON p.`admission_code` = a.`admission_code`
WHERE a.`date_out` IS NOT NULL
GROUP BY p.`admission_code`, p.`doctor_AMKA`
ORDER BY RAND()
LIMIT 120;

