-- fix gia query 3

-- --- 1ος Ασθενής (5 νοσηλείες στο 1ο δημοφιλές Τμήμα) ---
SET @dept1 = (SELECT `department_id` FROM `Admission` GROUP BY `department_id` ORDER BY COUNT(*) DESC LIMIT 1);
SET @pat1 = (SELECT `AMKA` FROM `Patient` LIMIT 1);
UPDATE `Admission` SET `patient_AMKA` = @pat1 WHERE `department_id` = @dept1 LIMIT 5;

-- --- 2ος Ασθενής (4 νοσηλείες σε άλλο Τμήμα) ---
SET @dept2 = (SELECT `department_id` FROM `Admission` WHERE `department_id` != @dept1 GROUP BY `department_id` ORDER BY COUNT(*) DESC LIMIT 1);
SET @pat2 = (SELECT `AMKA` FROM `Patient` WHERE `AMKA` != @pat1 LIMIT 1);
UPDATE `Admission` SET `patient_AMKA` = @pat2 WHERE `department_id` = @dept2 LIMIT 4;

-- --- 3ος Ασθενής (4 νοσηλείες σε 3ο Τμήμα) ---
SET @dept3 = (SELECT `department_id` FROM `Admission` WHERE `department_id` NOT IN (@dept1, @dept2) GROUP BY `department_id` ORDER BY COUNT(*) DESC LIMIT 1);
SET @pat3 = (SELECT `AMKA` FROM `Patient` WHERE `AMKA` NOT IN (@pat1, @pat2) LIMIT 1);
UPDATE `Admission` SET `patient_AMKA` = @pat3 WHERE `department_id` = @dept3 LIMIT 4;

SET SQL_SAFE_UPDATES = 1;

