-- 1. Διαλέγουμε έναν τυχαίο γιατρό για να τον κάνουμε "Super Χειρουργό"
SET @super_surgeon = (SELECT `AMKA` FROM `Doctor` LIMIT 1);

-- 2. Για να μην μας κόψει ο Trigger (που λέει ότι ο χειρουργός δεν μπορεί να είναι και βοηθός),
-- τον διαγράφουμε από τυχόν βοηθό σε όλα τα χειρουργεία.
DELETE FROM `Clinical_Event_Assistants` WHERE `staff_AMKA` = @super_surgeon;

-- 3. Βρίσκουμε 10 χειρουργεία και του τα "χρεώνουμε" ως κύριο χειρουργό!
UPDATE `Clinical_Event`
SET `main_surgeon_AMKA` = @super_surgeon
WHERE `clinical_event_code` IN (
    SELECT * FROM (
        SELECT ce.`clinical_event_code`
        FROM `Clinical_Event` ce
        JOIN `Medical_Procedures_Catalog` mpc ON ce.`procedure_code` = mpc.`procedure_code`
        WHERE mpc.`category` = 'Surgery'
        LIMIT 10
    ) AS temp
);

SET SQL_SAFE_UPDATES = 1;

