-- Συγχρονίζουμε τις ημερομηνίες του Triage με τις Εισαγωγές (Admissions)
-- Βάζουμε την άφιξη στο Triage να είναι 1-5 ώρες (60-300 λεπτά) ΠΡΙΝ την εισαγωγή!
UPDATE `Triage` t
JOIN `Admission` a ON t.patient_AMKA = a.patient_AMKA
SET t.arrival_date = DATE_SUB(a.date_in, INTERVAL FLOOR(1 + RAND() * 5) HOUR);

SET SQL_SAFE_UPDATES = 1;

SET SQL_SAFE_UPDATES = 0;

-- Επίπεδο 1: Αναμονή από 0 έως 15 λεπτά
UPDATE `Triage` t JOIN `Admission` a ON t.patient_AMKA = a.patient_AMKA
SET t.arrival_date = DATE_SUB(a.date_in, INTERVAL FLOOR(RAND() * 15) MINUTE) WHERE t.urgency_level = 1;

-- Επίπεδο 2: Αναμονή από 15 έως 60 λεπτά
UPDATE `Triage` t JOIN `Admission` a ON t.patient_AMKA = a.patient_AMKA
SET t.arrival_date = DATE_SUB(a.date_in, INTERVAL FLOOR(15 + RAND() * 45) MINUTE) WHERE t.urgency_level = 2;

-- Επίπεδο 3: Αναμονή από 1 έως 2.5 ώρες (60 - 150 λεπτά)
UPDATE `Triage` t JOIN `Admission` a ON t.patient_AMKA = a.patient_AMKA
SET t.arrival_date = DATE_SUB(a.date_in, INTERVAL FLOOR(60 + RAND() * 90) MINUTE) WHERE t.urgency_level = 3;

-- Επίπεδα 4 & 5: Αναμονή από 3 έως 6 ώρες (180 - 360 λεπτά)
UPDATE `Triage` t JOIN `Admission` a ON t.patient_AMKA = a.patient_AMKA
SET t.arrival_date = DATE_SUB(a.date_in, INTERVAL FLOOR(180 + RAND() * 180) MINUTE) WHERE t.urgency_level IN (4, 5);

SET SQL_SAFE_UPDATES = 1;